import{_ as d,A as o,o as n,c,j as t,a as r,C as s,X as i}from"./chunks/framework.Bo638KvF.js";const k=JSON.parse('{"title":"Metadata and representation: format","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/api/reference-format.md","filePath":"reference-format.md"}'),l={name:"rust/api/reference-format.md"};function h(u,e,p,m,b,f){const a=o("DocChoices");return n(),c("div",null,[e[0]||(e[0]=t("h1",{id:"metadata-and-representation-format",tabindex:"-1"},[r("Metadata and representation: format "),t("a",{class:"header-anchor",href:"#metadata-and-representation-format","aria-label":'Permalink to "Metadata and representation: format"'},"​")],-1)),e[1]||(e[1]=t("p",null,[r("Use "),t("code",null,"cellpack::format"),r(" to inspect "),t("strong",null,"bytes you already hold"),r(". It parses matrix-stream descriptors and chunk metadata; it does not open files or decode matrix values. For the wire layout and offset examples, read "),t("a",{href:"/CellPack/rust/docs/format.html"},"File and record format"),r(".")],-1)),s(a,{title:"Choose the metadata lifetime",items:[{label:"Borrow for this operation",when:"The input bytes stay alive and immutable.",detail:"parse_meta returns a cheap, copyable Meta view borrowing the metadata prefix."},{label:"Retain metadata independently",when:"The input buffer will be released or reused.",detail:"OwnedMeta keeps only the validated metadata prefix. Call view() to borrow it without reparsing."}]}),e[2]||(e[2]=i('<p>For ordinary matrix reads, start with <a href="/CellPack/rust/api/reference-store.html">store</a>. For encoding, decoding and mapping rows in memory, use <a href="/CellPack/rust/api/reference-scans.html">scans</a>.</p><h2 id="chunk-parsing-and-ownership" tabindex="-1">Chunk parsing and ownership <a class="header-anchor" href="#chunk-parsing-and-ownership" aria-label="Permalink to &quot;Chunk parsing and ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry point</th><th>Required input</th><th>Result</th></tr></thead><tbody><tr><td><code>parse_meta(bytes)</code></td><td>Bytes beginning at a chunk&#39;s <code>CPAK</code> header, covering the entire declared metadata prefix</td><td><code>Result&lt;Meta&lt;&#39;_&gt;&gt;</code>; sections borrow <code>bytes</code></td></tr><tr><td><code>OwnedMeta::new(bytes)</code></td><td>The same prefix, or a complete chunk</td><td>Validates and copies only <code>meta_len</code> bytes</td></tr><tr><td><code>OwnedMeta::from_vec(bytes)</code></td><td>An owned vector with that prefix</td><td>Validates, takes ownership and discards bytes after <code>meta_len</code></td></tr><tr><td><code>OwnedMeta::bytes()</code></td><td>A retained owner</td><td>Borrowed metadata bytes, exactly <code>meta_len</code> long</td></tr><tr><td><code>OwnedMeta::view()</code></td><td>A retained owner</td><td>A <code>Meta</code> tied to the borrow of the owner, without reparsing</td></tr></tbody></table><p>The records region need not be present. <code>parse_meta</code> checks the header, metadata section sizes, model frequencies, aggregate bounds, and the endpoints of the nnz table. It does <strong>not</strong> walk every row&#39;s table entry or validate record payloads. The owned form applies the same validation; owning bytes adds no stronger record guarantee.</p><h3 id="query-shape-and-allocation-bounds" tabindex="-1">Query shape and allocation bounds <a class="header-anchor" href="#query-shape-and-allocation-bounds" aria-label="Permalink to &quot;Query shape and allocation bounds&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Query</th><th>Meaning and units</th></tr></thead><tbody><tr><td><code>n_cells / n_dims</code></td><td>Local chunk row count / column count</td></tr><tr><td><code>value_width / index_width</code></td><td>Bytes per stored value / raw column ID; widths do not identify the numeric dtype</td></tr><tr><td><code>max_nnz</code></td><td>Largest declared row nnz: stored entries for sparse rows, nonzero values for dense rows</td></tr><tr><td><code>max_elems</code></td><td>Largest stored element count; a dense row stores <code>n_dims</code> elements</td></tr><tr><td><code>max_k / nnz_total</code></td><td>Largest row-local dictionary / sum of declared row nnz</td></tr><tr><td><code>renumbered / column_modes</code></td><td>Whether coded IDs were permuted / optional raw mode values in coded order</td></tr></tbody></table><p>A four-byte value could be <code>U32</code>, <code>I32</code> or <code>F32</code>. A CPK stream&#39;s <code>Dtype</code> supplies that interpretation; a standalone chunk only declares the byte width. Use codec sizing functions for decode buffers rather than treating <code>max_nnz</code> as a dense output length.</p><h3 id="locate-bytes-and-rows" tabindex="-1">Locate bytes and rows <a class="header-anchor" href="#locate-bytes-and-rows" aria-label="Permalink to &quot;Locate bytes and rows&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Query</th><th>Coordinate system or buffer requirement</th></tr></thead><tbody><tr><td><code>meta_len()</code></td><td>Metadata-prefix byte length, excluding padding before records</td></tr><tr><td><code>records_start()</code></td><td>Byte offset <strong>from the chunk start</strong>, including any page-alignment padding</td></tr><tr><td><code>records_len() / chunk_len()</code></td><td>Records-region bytes, including gaps / complete chunk bytes</td></tr><tr><td><code>page_size()</code></td><td><code>Some(bytes)</code> for packed records, <code>None</code> for an unpacked chunk</td></tr><tr><td><code>record_range(cell)</code></td><td>Byte range <strong>from the records-region start</strong>; <code>cell</code> is a zero-based local chunk row</td></tr><tr><td><code>records_of(chunk)</code></td><td>Borrows the records region from the matching complete chunk buffer</td></tr><tr><td><code>record(records, cell)</code></td><td>Borrows one row&#39;s encoded bytes from the complete records-region buffer</td></tr><tr><td><code>cell_nnz / cell_layout / cell_kind</code></td><td>Declared count / sparse-or-dense layout / raw flags for one local row</td></tr></tbody></table><p><code>record_range</code> and <code>cell_nnz</code> validate the requested row&#39;s extent or nnz entries. Out-of-range local rows return <code>Error::RowOutOfRange</code>; invalid table entries or short chunk/records buffers return <code>Error::CorruptMeta</code>. An empty row may have an empty record slice.</p><p><code>records_of</code> and <code>record</code> check extents, not the identity of a supplied buffer. Keep each <code>Meta</code>, records buffer and decode tables associated with the same encoded chunk. Returned record slices borrow the supplied records bytes, not the <code>Meta</code> value.</p><h3 id="read-a-record-count-without-decoding" tabindex="-1">Read a record count without decoding <a class="header-anchor" href="#read-a-record-count-without-decoding" aria-label="Permalink to &quot;Read a record count without decoding&quot;">​</a></h3><p><code>record_nnz(record)</code> returns the count in the record header and checks every byte it reads. An empty record returns zero; a missing, truncated or overflowing count returns <code>Error::CorruptRecord</code>. This helper accepts arbitrary bytes, but it only checks that count: it does not validate flags, index/value sections, or agreement with <code>Meta::cell_nnz</code>.</p><h2 id="matrix-stream-parsing-format-cpk" tabindex="-1">Matrix-stream parsing: format::cpk <a class="header-anchor" href="#matrix-stream-parsing-format-cpk" aria-label="Permalink to &quot;Matrix-stream parsing: format::cpk&quot;">​</a></h2><p>Use these functions when implementing a container or reader. A normal file reader can obtain the parsed descriptors from <code>CpkFile</code> instead.</p><table tabindex="0"><thead><tr><th>Step</th><th>Input and result</th><th>What is checked</th></tr></thead><tbody><tr><td><code>parse_superblock(bytes)</code></td><td>At least <code>SUPERBLOCK_LEN</code> bytes → owned <code>Superblock</code></td><td>Magic, version, reserved bytes, dtype/source codes, page size, shape and directory extent</td></tr><tr><td><code>superblock.directory_len()</code></td><td>Parsed descriptor → <code>n_chunks * ENTRY_LEN</code> bytes</td><td>Size query only</td></tr><tr><td><code>parse_directory(super_bytes, &amp;superblock, directory_bytes)</code></td><td>The <strong>same</strong> complete superblock bytes and descriptor, plus at least <code>directory_len()</code> directory bytes → owned <code>Vec&lt;ChunkEntry&gt;</code></td><td>Header/directory hash, row coverage and aligned, ascending, non-overlapping chunk extents</td></tr></tbody></table><p>Read the directory at <code>superblock.directory_offset</code>, measured from the CPK stream start. <code>parse_directory</code> does not fetch it, parse individual chunk metadata, or check that payload bytes actually exist in the backing file. Keep the original superblock buffer until directory parsing finishes; the returned descriptors contain values and do not borrow either input.</p><table tabindex="0"><thead><tr><th>Type or constant</th><th>Contract</th></tr></thead><tbody><tr><td><code>Superblock</code></td><td>Matrix shape, numeric dtype, original input layout, page size, chunk count/target rows, directory offset and declared stream length</td></tr><tr><td><code>ChunkEntry</code></td><td>Matrix <code>first_row</code>, local row count, stream-relative byte <code>offset</code>, total chunk <code>len</code> and metadata <code>meta_len</code></td></tr><tr><td><code>Dtype</code></td><td>Ten numeric types; <code>width()</code> is bytes per value; <code>f32(bytes)</code> converts the first stored value</td></tr><tr><td><code>SourceLayout</code></td><td>The matrix arrived as CSR or dense; not a per-record coding decision</td></tr><tr><td><code>RecordLayout</code></td><td>One record stores sparse entries or every column&#39;s value</td></tr><tr><td><code>SUPERBLOCK_LEN / ENTRY_LEN</code></td><td>4096 / 40 bytes; exported under <code>format::cpk</code></td></tr></tbody></table><p><code>Dtype::f32(bytes)</code> requires at least <code>width()</code> bytes; a short slice can panic. Integer values beyond exact <code>f32</code> representation and <code>F64</code> values can round.</p><div class="warning custom-block"><p class="custom-block-title">Validation boundary</p><p>The superblock/directory hash is non-cryptographic and excludes record payloads. Successful metadata parsing does not make arbitrary inner records safe to decode. Follow the <a href="/CellPack/rust/api/contracts.html#failure-and-validation-boundary">trusted-data contract</a>.</p></div><h2 id="complete-chunk-api" tabindex="-1">Complete chunk API <a class="header-anchor" href="#complete-chunk-api" aria-label="Permalink to &quot;Complete chunk API&quot;">​</a></h2><h3 id="re-exports" tabindex="-1">Re-exports <a class="header-anchor" href="#re-exports" aria-label="Permalink to &quot;Re-exports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-format-cpk-struct-ChunkEntry.html"><code>ChunkEntry</code></a></td><td>One chunk: rows first_row..first_row + n_rows at offset , len bytes of which the first meta_len are its metadata.</td></tr><tr><td><a href="/CellPack/rust/api/generated-format-cpk-enum-Dtype.html"><code>Dtype</code></a></td><td>Numeric type of a matrix’s values; its width is the chunks’ value width.</td></tr><tr><td><a href="/CellPack/rust/api/generated-format-cpk-enum-SourceLayout.html"><code>SourceLayout</code></a></td><td>The form a matrix arrived in.</td></tr><tr><td><a href="/CellPack/rust/api/generated-format-cpk-struct-Superblock.html"><code>Superblock</code></a></td><td>Decoded superblock fields.</td></tr></tbody></table><h3 id="structs" tabindex="-1">Structs <a class="header-anchor" href="#structs" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-format-struct-Meta.html"><code>Meta</code></a></td><td>Interpretation of a chunk’s metadata bytes. Holds no data of its own: header fields are decoded once, sections are borrowed.</td></tr><tr><td><a href="/CellPack/rust/api/generated-format-struct-OwnedMeta.html"><code>OwnedMeta</code></a></td><td>Immutable metadata bytes and a validated descriptor. Views borrow only this owner; section offsets avoid self-referential pointers and lifetime extension.</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-format-enum-RecordLayout.html"><code>RecordLayout</code></a></td><td>How a record stores its elements.</td></tr></tbody></table><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-format-fn-parse_meta.html"><code>parse_meta</code></a></td><td>Parses metadata from the start of bytes (the metadata alone or a whole chunk). Checks the header and section sizes; per-cell table entries are checked where they are read.</td></tr><tr><td><a href="/CellPack/rust/api/generated-format-fn-record_nnz.html"><code>record_nnz</code></a></td><td>Element count of a record from its header alone: the varint after the flags byte (0 for an empty record). For a sparse record it counts stored entries (explicit zeros included); for a dense record, non-zero values. A caller can compare it with metadata before committing to a decode.</td></tr></tbody></table><h2 id="complete-matrix-stream-api" tabindex="-1">Complete matrix-stream API <a class="header-anchor" href="#complete-matrix-stream-api" aria-label="Permalink to &quot;Complete matrix-stream API&quot;">​</a></h2><h3 id="structs-1" tabindex="-1">Structs <a class="header-anchor" href="#structs-1" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-format-cpk-struct-ChunkEntry.html"><code>ChunkEntry</code></a></td><td>One chunk: rows first_row..first_row + n_rows at offset , len bytes of which the first meta_len are its metadata.</td></tr><tr><td><a href="/CellPack/rust/api/generated-format-cpk-struct-Superblock.html"><code>Superblock</code></a></td><td>Decoded superblock fields.</td></tr></tbody></table><h3 id="enums-1" tabindex="-1">Enums <a class="header-anchor" href="#enums-1" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-format-cpk-enum-Dtype.html"><code>Dtype</code></a></td><td>Numeric type of a matrix’s values; its width is the chunks’ value width.</td></tr><tr><td><a href="/CellPack/rust/api/generated-format-cpk-enum-SourceLayout.html"><code>SourceLayout</code></a></td><td>The form a matrix arrived in.</td></tr></tbody></table><h3 id="constants" tabindex="-1">Constants <a class="header-anchor" href="#constants" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-format-cpk-constant-ENTRY_LEN.html"><code>ENTRY_LEN</code></a></td><td>Bytes of one directory entry.</td></tr><tr><td><a href="/CellPack/rust/api/generated-format-cpk-constant-SUPERBLOCK_LEN.html"><code>SUPERBLOCK_LEN</code></a></td><td>Bytes reserved for the superblock at the start of the file.</td></tr></tbody></table><h3 id="functions-1" tabindex="-1">Functions <a class="header-anchor" href="#functions-1" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-format-cpk-fn-parse_directory.html"><code>parse_directory</code></a></td><td>Parses and checks the directory against its superblock: the hash, rows that tile 0..n_rows in order, and page-aligned, ascending, non-overlapping chunks after the superblock and before the directory.</td></tr><tr><td><a href="/CellPack/rust/api/generated-format-cpk-fn-parse_superblock.html"><code>parse_superblock</code></a></td><td>Parses a superblock (at least SUPERBLOCK_LEN bytes) and checks its fields against each other; the hash is checked by parse_directory .</td></tr></tbody></table>',38))])}const g=d(l,[["render",h]]);export{k as __pageData,g as default};
